// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address firstOwner, address newOwner) public {
        vm.assume(firstOwner != address(0));
        vm.assume(newOwner != address(0));
        // initial owner is address(0) (initialize never called), so address(0) is the current owner
        vm.prank(address(0));
        c.transferOwnership(firstOwner);
        vm.prank(firstOwner);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner, "owner must equal the most recently transferred address");
    }
}
